-- The two checklists published on 2026-11-13: Being a Grandparent Without
-- Taking Over (Grandparenting) and When Someone You Love Is Dying
-- (End of Life).
-- Generated by `python3 tools/checklists_sql.py being-a-grandparent-without-taking-over
-- when-someone-you-love-is-dying`; the repo copy in data/checklists.json is
-- the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('being-a-grandparent-without-taking-over', 'Being a Grandparent Without Taking Over', 'For grandparents who want to help without stepping on the parents. It asks how they do it before offering how you did, spends your one opinion carefully, finds something that is yours with the child, and offers an evening rather than advice.', 'Grandparenting', '["Ask how they do it before offering how you did — their house, their rules, even when yours worked.", "Say yes to the help they actually asked for — the useful kind is rarely the kind you imagined.", "Keep the comment about the feeding to yourself — you get one opinion a month, so spend it well.", "Have one thing that is yours with the child — a walk, a recipe, a game nobody else plays.", "Give the parents an evening, not advice — two hours off is worth more than any suggestion.", "Ask before the sweets and the screen time — undermining is usually accidental and still lands.", "Let the parent correct you in front of the child — backing them up is the whole job here.", "Say what you can and cannot manage honestly — a grandparent stretched thin helps nobody.", "Remember you are not the one in charge now — that loss is real and worth sitting with quietly."]'::jsonb, 'weekly', array['Family', 'Boundaries', 'Relationships']::text[], 1, '2026-11-13T16:00:00+00:00'::timestamptz),
  ('when-someone-you-love-is-dying', 'When Someone You Love Is Dying', 'For the weeks when someone you love is dying and nothing prepares you. It asks the team what to expect, gets their wishes written down, splits the nights with somebody, makes room for sitting in silence, and keeps you eating and sleeping.', 'End of Life', '["Ask the team how long, and what to expect — not knowing is heavier than knowing.", "Say the thing you would regret not saying — it does not have to be a speech.", "Find out what they want and write it down — wishes are easier to honor in writing.", "Take the night shifts in turns with someone — nobody can hold this alone for weeks.", "Sit without talking sometimes — presence asks less of them than conversation does.", "Eat and sleep on something like a schedule — you are no use to them running on nothing.", "Keep 988 in your phone for the worst nights — call or text, any time, free across the United States.", "Let other people do the practical things — somebody else can field the calls and the food.", "Say goodbye more than once — there is no single right moment, and rarely the one you pictured."]'::jsonb, 'as needed', array['Grief', 'Caregiving', 'Loss']::text[], 1, '2026-11-13T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
